{
  "days": [
    {
      "day": 1,
      "activities": [
        {
          "time": "morning",
          "name": "Kuopio Market Square & Market Hall",
          "address": "Kauppakatu 45, 70100 Kuopio",
          "opening_hours": "Market Square: Mon-Fri 7-17, Sat 7-15; Market Hall: Mon-Fri 9-17, Sat 9-15",
          "cost_eur": "0 (cost for purchases varies)",
          "description": "Experience the vibrant heart of Kuopio. Explore the outdoor market for local produce and street food like Lörtsy, then step inside the historic Market Hall for various vendors and delicacies."
        },
        {
          "time": "afternoon",
          "name": "Puijo Tower",
          "address": "Puijontie 49, 70300 Kuopio",
          "opening_hours": "Daily 10-18 (check website for seasonal variations)",
          "cost_eur": "7-10",
          "description": "Ascend to the top of Kuopio's iconic observation tower for breathtaking panoramic views of the city and the surrounding Finnish Lakeland. Enjoy a coffee or meal at the revolving restaurant."
        },
        {
          "time": "evening",
          "name": "Dinner at a local restaurant (e.g., Ravintola Isä Camillo)",
          "address": "Kauppakatu 28, 70100 Kuopio",
          "opening_hours": "Tue-Sat 17-23 (check specific restaurant for exact hours)",
          "cost_eur": "30-50 per person",
          "description": "Savor modern Finnish cuisine or international dishes in a cozy setting. Ravintola Isä Camillo is a well-regarded option known for its quality ingredients and atmosphere."
        }
      ]
    },
    {
      "day": 2,
      "activities": [
        {
          "time": "morning",
          "name": "Kallavesi Lake Cruise (e.g., MS Ukko)",
          "address": "Kuopio Passenger Harbour, Matkustajasatama, 70100 Kuopio",
          "opening_hours": "Seasonal (May-Sept), typically daily departures around 11:00, 14:00, 17:00 (check operator schedules)",
          "cost_eur": "20-30",
          "description": "Embark on a scenic cruise on Lake Kallavesi, part of the vast Finnish Lakeland. Enjoy the serene waters, picturesque islands, and views of Kuopio from a different perspective."
        },
        {
          "time": "afternoon",
          "name": "Väinölänniemi Park & Beach",
          "address": "Väinölänniemenkatu, 70100 Kuopio",
          "opening_hours": "Always open",
          "cost_eur": "0",
          "description": "Relax and unwind at Väinölänniemi, a beautiful park peninsula offering sandy beaches, walking paths, and green spaces. Perfect for a leisurely stroll or enjoying the lakeside atmosphere."
        },
        {
          "time": "evening",
          "name": "Taste Traditional Kalakukko",
          "address": "Various bakeries or Kuopio Market Hall, Kauppakatu 45, 70100 Kuopio",
          "opening_hours": "Market Hall: Mon-Fri 9-17, Sat 9-15 (check specific bakery hours)",
          "cost_eur": "10-25 (depending on size)",
          "description": "Indulge in Kalakukko, a traditional Finnish fish pie from the Savonia region. This unique delicacy features fish (often perch or vendace) and pork baked inside a rye crust."
        }
      ]
    },
    {
      "day": 3,
      "activities": [
        {
          "time": "morning",
          "name": "Kuopio Museum",
          "address": "Museokatu 1, 70100 Kuopio",
          "opening_hours": "Tue-Fri 10-17, Sat-Sun 10-16 (Closed Mondays)",
          "cost_eur": "8-10",
          "description": "Explore one of Finland's oldest museum buildings. The Kuopio Museum showcases the natural and cultural history of the Kuopio region, offering insights into local heritage and environment."
        },
        {
          "time": "afternoon",
          "name": "Kuopio Art Museum",
          "address": "Snellmaninkatu 10, 70100 Kuopio",
          "opening_hours": "Tue-Fri 10-17, Sat-Sun 10-16 (Closed Mondays)",
          "cost_eur": "8-10",
          "description": "Discover Finnish art from the 19th century to the present day, with a particular focus on artists and themes from Eastern Finland. The museum hosts engaging temporary exhibitions."
        },
        {
          "time": "evening",
          "name": "Souvenir Shopping / Lakeside Walk",
          "address": "Kuopio City Center / Kuopio Passenger Harbour area",
          "opening_hours": "Shops typically Mon-Fri 10-18, Sat 10-16. Lakeside walk always open.",
          "cost_eur": "0 (cost for purchases varies)",
          "description": "Spend your final hours browsing local craft shops for unique Finnish souvenirs or take a last leisurely stroll along the beautiful Kuopio waterfront, soaking in the tranquil atmosphere before departure."
        }
      ]
    }
  ]
}
